1	// USD prices per 1M tokens, used to estimate the cost of each model step for the per-turn caps.
2	//
3	// Source: DeepSeek's official pricing page, https://api-docs.deepseek.com/quick_start/pricing
4	// (checked 2026-10-12). deepseek-flash (DeepSeek-V4.1-Flash) at PEAK rates:
5	//   input (cache miss) $0.30, input (cache hit) $0.006, output $1.20.
6	// Off-peak rates are half of these. For safety the caps always use the peak rates and count every
7	// input token at the cache-miss rate, so the estimate never under-counts the real bill.
8	
9	export type ModelPrice = { inputPerMTok: number; outputPerMTok: number };
10	
11	const PRICES: Record<string, ModelPrice> = {
12	  // The legacy names are served by DeepSeek-V4.1-Flash and billed at the Flash price.
13	  "deepseek/deepseek-flash": { inputPerMTok: 0.3, outputPerMTok: 1.2 },
14	  "deepseek/deepseek-v4-flash": { inputPerMTok: 0.3, outputPerMTok: 1.2 },
15	  "deepseek/deepseek-v4-flash-vision-exp": { inputPerMTok: 0.3, outputPerMTok: 1.2 },
16	  "deepseek/deepseek-v4-pro": { inputPerMTok: 1.32, outputPerMTok: 3.96 },
17	};
18	
19	/** Deliberately high, so a model missing from the table is over- rather than under-counted. */
20	export const FALLBACK_PRICE: ModelPrice = { inputPerMTok: 5, outputPerMTok: 25 };
21	
22	const warned = new Set<string>();
23	
24	/**
25	 * Price for a model id, either "provider/model" or a bare model id as reported by the provider
26	 * ("deepseek-flash"). Unknown models get FALLBACK_PRICE and a one-time warning.
27	 */
28	export function priceFor(modelId: string | undefined): ModelPrice {
29	  const id = (modelId ?? "").trim().toLowerCase();
30	  const exact = PRICES[id];
31	  if (exact) return exact;
32	  const bare = id.includes("/") ? id.slice(id.lastIndexOf("/") + 1) : id;
33	  const match = Object.entries(PRICES).find(([key]) => key.slice(key.lastIndexOf("/") + 1) === bare);
34	  if (match) return match[1];
35	  if (!warned.has(id)) {
36	    warned.add(id);
37	    console.warn(`[usage] no price for model "${modelId ?? "unknown"}"; using the conservative fallback price.`);
38	  }
39	  return FALLBACK_PRICE;
40	}
41	
42	/** Estimated USD cost of one model call. */
43	export function estimateCostUsd(modelId: string | undefined, inputTokens: number, outputTokens: number): number {
44	  const price = priceFor(modelId);
45	  return (inputTokens * price.inputPerMTok + outputTokens * price.outputPerMTok) / 1_000_000;
46	}
47

1	import type { RequestContext } from "@mastra/core/request-context";
2	import type { ProcessInputStepArgs, ProcessOutputStepArgs, Processor } from "@mastra/core/processors";
3	import type { TurnCaps } from "./caps";
4	import { estimateCostUsd } from "./pricing";
5	
6	/**
7	 * RequestContext key holding the current turn's TurnBudget. Set only by the server
8	 * (src/chat-api.ts). Delegated sub-agents get a shallow copy of the caller's RequestContext, so
9	 * they see the same TurnBudget object and their model calls count toward the same turn.
10	 */
11	export const TURN_BUDGET_KEY = "nlhack.turnBudget";
12	
13	export type CapReason = "cost" | "tokens";
14	
15	/** Shape of the `data-turn-usage` stream part (and of the usage saved on the reply). */
16	export type TurnUsage = {
17	  costUsd: number;
18	  tokens: number;
19	  inputTokens: number;
20	  outputTokens: number;
21	  steps: number;
22	  capCostUsd: number;
23	  capTokens: number;
24	  capped: boolean;
25	  reason: CapReason | null;
26	  /** True on the last part of a turn. */
27	  final: boolean;
28	  /** The turn's Neatlogs trace id (set by src/chat-api.ts on what it streams and saves). */
29	  traceId?: string;
30	};
31	
32	type StepUsage = { inputTokens?: number; outputTokens?: number; totalTokens?: number };
33	
34	/** Usage and caps of one chat turn: every model step of the agent and of any agent it delegates to. */
35	export class TurnBudget {
36	  inputTokens = 0;
37	  outputTokens = 0;
38	  costUsd = 0;
39	  steps = 0;
40	  reason: CapReason | null = null;
41	  /** Called after every recorded model step (the server streams it as `data-turn-usage`). */
42	  onStep?: (usage: TurnUsage) => void;
43	
44	  constructor(readonly caps: TurnCaps) {}
45	
46	  get tokens(): number {
47	    return this.inputTokens + this.outputTokens;
48	  }
49	
50	  get capped(): boolean {
51	    return this.reason !== null;
52	  }
53	
54	  /** Adds one model step's usage, then marks the turn capped once either cap is exceeded. */
55	  record(modelId: string | undefined, usage: StepUsage | undefined): void {
56	    const input = safeCount(usage?.inputTokens);
57	    // Reasoning tokens are part of the output count; if a provider reports a larger total, the
58	    // difference is counted as output so nothing goes uncounted.
59	    const output = Math.max(safeCount(usage?.outputTokens), safeCount(usage?.totalTokens) - input);
60	    this.inputTokens += input;
61	    this.outputTokens += output;
62	    this.costUsd += estimateCostUsd(modelId, input, output);
63	    this.steps += 1;
64	    if (!this.reason) {
65	      if (this.costUsd > this.caps.costCapUsd) this.reason = "cost";
66	      else if (this.tokens > this.caps.tokenCap) this.reason = "tokens";
67	    }
68	    this.onStep?.(this.snapshot(false));
69	  }
70	
71	  snapshot(final: boolean): TurnUsage {
72	    return {
73	      costUsd: round(this.costUsd),
74	      tokens: this.tokens,
75	      inputTokens: this.inputTokens,
76	      outputTokens: this.outputTokens,
77	      steps: this.steps,
78	      capCostUsd: this.caps.costCapUsd,
79	      capTokens: this.caps.tokenCap,
80	      capped: this.capped,
81	      reason: this.reason,
82	      final,
83	    };
84	  }
85	
86	  /** User-facing explanation, used as the note on a capped reply. */
87	  cappedMessage(): string {
88	    if (this.reason === "cost") {
89	      return `Stopped: this reply reached its cost limit (about $${this.costUsd.toFixed(4)} used of $${this.caps.costCapUsd} per message). You can raise the limit for this agent and ask again.`;
90	    }
91	    if (this.reason === "tokens") {
92	      return `Stopped: this reply reached its token limit (${this.tokens.toLocaleString("en-US")} used of ${this.caps.tokenCap.toLocaleString("en-US")} tokens per message). You can raise the limit for this agent and ask again.`;
93	    }
94	    return "";
95	  }
96	}
97	
98	export function turnBudgetFrom(requestContext: RequestContext | undefined): TurnBudget | undefined {
99	  const value = typeof requestContext?.get === "function" ? requestContext.get(TURN_BUDGET_KEY) : undefined;
100	  return value instanceof TurnBudget ? value : undefined;
101	}
102	
103	/**
104	 * Enforces the turn's caps on every agent it is attached to (all agents, so delegated sub-agents
105	 * count too). After each model step it records the step's usage; once a cap is exceeded it trips
106	 * the run (TripWire), so no further model call happens. Mastra still executes the tool calls that
107	 * capping step already requested; a delegation among them is stopped before its first model call.
108	 * A run without a TurnBudget in its RequestContext (CLI, `mastra dev`) is not limited.
109	 */
110	class TurnBudgetProcessor implements Processor<"turn-budget"> {
111	  readonly id = "turn-budget";
112	  readonly name = "Turn usage caps";
113	
114	  // Before each model call: a turn that is already capped (e.g. a sub-agent delegated by the
115	  // step that hit the cap) never calls the model. Also notes this step's model for pricing.
116	  processInputStep({ requestContext, abort, model, state }: ProcessInputStepArgs): void {
117	    const budget = turnBudgetFrom(requestContext);
118	    if (!budget) return;
119	    if (budget.capped) abort(budget.cappedMessage(), { metadata: budget.snapshot(false) });
120	    state[MODEL_STATE_KEY] = typeof model === "object" && model ? `${model.provider}/${model.modelId}` : undefined;
121	  }
122	
123	  // After each model call: count its usage, and stop the run once a cap is exceeded.
124	  processOutputStep({ requestContext, usage, abort, messageList, state }: ProcessOutputStepArgs) {
125	    const budget = turnBudgetFrom(requestContext);
126	    if (!budget) return messageList;
127	    const modelId = state[MODEL_STATE_KEY];
128	    budget.record(typeof modelId === "string" ? modelId : undefined, usage);
129	    if (budget.capped) abort(budget.cappedMessage(), { metadata: budget.snapshot(false) });
130	    return messageList;
131	  }
132	}
133	
134	const MODEL_STATE_KEY = "modelId";
135	
136	export const turnBudgetProcessor = new TurnBudgetProcessor();
137	
138	function safeCount(value: number | undefined): number {
139	  return typeof value === "number" && Number.isFinite(value) && value > 0 ? value : 0;
140	}
141	
142	function round(usd: number): number {
143	  return Math.round(usd * 1e6) / 1e6;
144	}
145	
146	/** Spread into every Agent config: `...turnCapProcessors`. */
147	export const turnCapProcessors = {
148	  inputProcessors: [turnBudgetProcessor],
149	  outputProcessors: [turnBudgetProcessor],
150	};
151

